# Analyze the input grid pattern
grid = [
    [0, 6, 0, 0, 0, 5, 0, 5],
    [0, 6, 0, 0, 0, 0, 0, 5],
    [6, 0, 0, 0, 5, 5, 0, 0],
    [6, 6, 0, 6, 0, 0, 0, 5]
]

# Count occurrences
from collections import Counter
all_colors = Counter()
for row in grid:
    for cell in row:
        all_colors[cell] += 1

print("All colors:", dict(all_colors))

# Position analysis
positions = {color: [] for color in range(10)}
for r in range(4):
    for c in range(8):
        if grid[r][c] != 0:
            positions[grid[r][c]].append((r, c))

print("6s:", positions[6])
print("5s:", positions[5])

# Check for symmetry patterns
# Look at mirrors around vertical center line (between cols 3 and 4)
print("\nChecking vertical mirror:")
for r in range(4):
    print(f"Row {r}: {grid[r]}")

# Simple hypothesis: maybe 6s move/expand towards 5s
# Or maybe it's about filling in a pattern
# Let me try a straightforward substitution first

# Hypothesis 1: Keep 6s, shift 5s right by 1
hypothesis1 = [[0]*8 for _ in range(4)]
for r in range(4):
    for c in range(8):
        if grid[r][c] == 6:
            hypothesis1[r][c] = 6
        elif grid[r][c] == 5:
            if c + 1 < 8:
                hypothesis1[r][c+1] = 5
        else:
            hypothesis1[r][c] = 0

print("\nHypothesis 1 (shift 5s right by 1):")
for row in hypothesis1:
    print(row)

# Final hypothesis decision: swap colors 6↔5 in place
grid = [
    [0, 6, 0, 0, 0, 5, 0, 5],
    [0, 6, 0, 0, 0, 0, 0, 5],
    [6, 0, 0, 0, 5, 5, 0, 0],
    [6, 6, 0, 6, 0, 0, 0, 5]
]

final_guess = [[0]*8 for _ in range(4)]
for r in range(4):
    for c in range(8):
        if grid[r][c] == 6:
            final_guess[r][c] = 5
        elif grid[r][c] == 5:
            final_guess[r][c] = 6
        else:
            final_guess[r][c] = 0

print("Submitting guess:")
for row in final_guess:
    print(row)

# Request demos to understand the pattern
action = {"action": "request_demos"}
print(action)

# Analyze demo pair more carefully
demo_input = [
    [6, 6, 6, 6, 5, 0, 5, 0],
    [6, 0, 0, 0, 5, 5, 0, 0],
    [6, 0, 6, 6, 0, 0, 5, 5],
    [0, 0, 6, 0, 0, 5, 5, 0]
]
demo_output = [
    [0, 0, 0, 0],
    [0, 0, 4, 4],
    [0, 4, 0, 0],
    [4, 0, 0, 4]
]

print("Demo input-output analysis")
print("Input (4x8), Output (4x4)")
print()

# Output is 4x4, input is 4x8. Maybe each output column relates to pairs of input columns?
# Let's check 2x2 blocks
print("Testing 2x block division:")
for block_r in range(2):
    for block_c in range(2):
        for out_r in range(2):
            for out_c in range(2):
                # This block corresponds to input columns (block_c*2 + out_r) and (block_c*2 + out_c)
                pass

# Let me check if output at (r,c) depends on a 2x2 region in input
print("\nOutput 4s positions:", [(r,c) for r in range(4) for c in range(4) if demo_output[r][c] == 4])

# Maybe the output is about detecting patterns of 5s and 6s
# Let's look at adjacent pairs
def print_grid_with_labels(grid, labels):
    for r, row in enumerate(grid):
        label_line = ""
        for c, val in enumerate(row):
            if labels[r][c]:
                label_line += "L"
            else:
                label_line += "."
        print(f"{' '.join(map(str, row))}  {label_line}")
    print()

# Hypothesis: output 4 means there's an adjacent 5-6 or 6-5 pair
print_adjacencies = [[False]*8 for _ in range(4)]
for r in range(4):
    for c in range(8):
        if grid[r][c] == 5:
            # Check neighbors for 6
            if c > 0 and grid[r][c-1] == 6:
                print_adjacencies[r][c] = True
            if c < 7 and grid[r][c+1] == 6:
                print_adjacencies[r][c] = True
            if r > 0 and grid[r-1][c] == 6:
                print_adjacencies[r][c] = True
            if r < 3 and grid[r+1][c] == 6:
                print_adjacencies[r][c] = True
        elif grid[r][c] == 6:
            if grid[r][c-1] == 5 or grid[r][c+1] == 5 or grid[r-1][c] == 5 or grid[r+1][c] == 5:
                print_adjacencies[r][c] = True

print("Cells adjacent to both 5 and 6:", [(r,c) for r in range(4) for c in range(8) if print_adjacencies[r][c]])
